+
+/* Android and other touch screens: keep the scene gesture-safe and controls easy to hit. */
+#game,#scene{touch-action:none;overscroll-behavior:none;-webkit-tap-highlight-color:transparent}
+#game{user-select:none;-webkit-user-select:none}
+@media(pointer:coarse){
+ .touch-controls{bottom:calc(22px + env(safe-area-inset-bottom));left:calc(18px + env(safe-area-inset-left));right:calc(18px + env(safe-area-inset-right));}
+ .touch-controls>div{grid-template-columns:repeat(3,58px);grid-template-rows:repeat(2,58px);gap:7px}
+ .touch-controls button{width:58px;height:58px;border-radius:50%;font-size:21px;background:rgba(20,22,20,.62);border-color:rgba(233,225,209,.42);box-shadow:0 3px 14px rgba(0,0,0,.24);-webkit-user-select:none;user-select:none}
+ .touch-controls button:active{background:rgba(194,164,119,.78);transform:scale(.96)}
+ .touch-controls .touch-interact{width:88px;height:58px;padding:0 8px;border-radius:999px;font-size:10px!important;letter-spacing:.07em;background:rgba(186,157,113,.83);color:#171713}
+ .bottomline{bottom:calc(166px + env(safe-area-inset-bottom));left:18px;right:18px;font-size:9px;letter-spacing:.04em}
+ .subtitles{bottom:calc(184px + env(safe-area-inset-bottom));}
+ .topline{top:calc(16px + env(safe-area-inset-top));}
+}
+@media(max-height:520px) and (pointer:coarse){
+ .touch-controls{bottom:calc(10px + env(safe-area-inset-bottom))}
+ .touch-controls>div{grid-template-columns:repeat(3,48px);grid-template-rows:repeat(2,48px);gap:5px}
+ .touch-controls button{width:48px;height:48px;font-size:18px}
+ .touch-controls .touch-interact{width:76px;height:50px}
+ .bottomline{bottom:calc(118px + env(safe-area-inset-bottom))}
+ .subtitles{bottom:calc(132px + env(safe-area-inset-bottom))}
+}
